import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { mcpGatewayAuditCountsRetrieve, mcpGatewayAuditList } from '../generated/api'
import { AuditCountsApi, MCPAuditEventApi } from '../generated/api.schemas'

export type AuditQuickFilter = 'all' | 'agents' | 'approvals' | 'blocked'

const PAGE_SIZE = 10

function currentProjectId(): string {
    return String(teamLogic.values.currentTeamId)
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface gatewayAuditLogicValues {
    auditResponse: {
        count: number
        results: MCPAuditEventApi[]
    }
    auditResponseLoading: boolean
    callerFilter: string
    counts: AuditCountsApi | null
    countsLoading: boolean
    hasActiveFilters: boolean
    page: number
    quickFilter: AuditQuickFilter
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface gatewayAuditLogicActions {
    clearFilters: () => {
        value: true
    }
    loadAudit: (_: void) => void
    loadAuditFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadAuditSuccess: (
        auditResponse: {
            count: number
            results: MCPAuditEventApi[]
        },
        payload?: void
    ) => {
        auditResponse: {
            count: number
            results: MCPAuditEventApi[]
        }
        payload?: void
    }
    loadCounts: (_: void) => void
    loadCountsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadCountsSuccess: (
        counts: AuditCountsApi,
        payload?: void
    ) => {
        counts: AuditCountsApi
        payload?: void
    }
    setCallerFilter: (callerFilter: string) => {
        callerFilter: string
    }
    setPage: (page: number) => {
        page: number
    }
    setQuickFilter: (quickFilter: AuditQuickFilter) => {
        quickFilter: AuditQuickFilter
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface gatewayAuditLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        hasActiveFilters: (quickFilter: AuditQuickFilter, callerFilter: string) => boolean
    }
}

export type gatewayAuditLogicType = MakeLogicType<
    gatewayAuditLogicValues,
    gatewayAuditLogicActions,
    Record<string, any>,
    gatewayAuditLogicMeta
>

export const gatewayAuditLogic = kea<gatewayAuditLogicType>([
    path(['products', 'mcp_store', 'frontend', 'gateway', 'gatewayAuditLogic']),

    actions({
        clearFilters: true,
        setCallerFilter: (callerFilter: string) => ({ callerFilter }),
        setQuickFilter: (quickFilter: AuditQuickFilter) => ({ quickFilter }),
        setPage: (page: number) => ({ page }),
    }),

    loaders(({ values }) => ({
        auditResponse: [
            { count: 0, results: [] as MCPAuditEventApi[] } as { count: number; results: MCPAuditEventApi[] },
            {
                loadAudit: async (_: void, breakpoint) => {
                    const response = await mcpGatewayAuditList(currentProjectId(), {
                        quick_filter: values.quickFilter,
                        actor_service_account_id: values.callerFilter === 'all' ? undefined : values.callerFilter,
                        limit: PAGE_SIZE,
                        offset: (values.page - 1) * PAGE_SIZE,
                    })
                    breakpoint()
                    return { count: response.count, results: response.results }
                },
            },
        ],
        counts: [
            null as AuditCountsApi | null,
            {
                loadCounts: async (_: void, breakpoint) => {
                    const counts = await mcpGatewayAuditCountsRetrieve(currentProjectId(), {
                        actor_service_account_id: values.callerFilter === 'all' ? undefined : values.callerFilter,
                    })
                    breakpoint()
                    return counts
                },
            },
        ],
    })),

    reducers({
        quickFilter: [
            'all' as AuditQuickFilter,
            { setQuickFilter: (_, { quickFilter }) => quickFilter, clearFilters: () => 'all' },
        ],
        callerFilter: ['all', { setCallerFilter: (_, { callerFilter }) => callerFilter, clearFilters: () => 'all' }],
        page: [
            1,
            {
                setPage: (_, { page }) => page,
                setQuickFilter: () => 1,
                setCallerFilter: () => 1,
                clearFilters: () => 1,
            },
        ],
    }),

    selectors({
        hasActiveFilters: [
            (s) => [s.quickFilter, s.callerFilter],
            (quickFilter: AuditQuickFilter, callerFilter: string): boolean =>
                quickFilter !== 'all' || callerFilter !== 'all',
        ],
    }),

    listeners(({ actions }) => ({
        setQuickFilter: () => {
            actions.loadAudit()
            actions.loadCounts()
        },
        setCallerFilter: () => {
            actions.loadAudit()
            actions.loadCounts()
        },
        clearFilters: () => {
            actions.loadAudit()
            actions.loadCounts()
        },
        setPage: () => actions.loadAudit(),
    })),

    afterMount(({ actions }) => {
        actions.loadAudit()
        actions.loadCounts()
    }),
])

export { PAGE_SIZE as AUDIT_PAGE_SIZE }
